-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 13 recettes, 11 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"texas-brisket","country":"US","original":"Central Texas smoked brisket","title":"Brisket fumé du centre du Texas (poitrine de bœuf sel-poivre)","en":"Central Texas smoked brisket","es":"Brisket ahumado del centro de Texas","desc":"Poitrine de bœuf entière assaisonnée seulement de sel et de gros poivre noir, fumée 12 heures au bois de chêne post oak, servie au poids sur papier boucher à Lockhart et Austin.","cat":"Grillade","diff":"hard","prep":30,"cook":720,"serv":12,"place":{"slug":"us-lockhart","name":"Lockhart","type":"city","lat":29.8849,"lng":-97.67,"summary":"Petite ville texane proclamée capitale du barbecue du Texas."},"ing":[["Poitrine de bœuf entière (packer brisket)",6,"kg",null],["Gros sel",4,"c. à soupe",null],["Poivre noir concassé gros",4,"c. à soupe",null],["Bois de chêne",1,"portion","pour le fumoir"],["Papier boucher",1,"rouleau",null],["Pain de mie blanc, oignon, cornichons",1,"portion","pour servir"]],"steps":["Parer la graisse à 6 mm d’épaisseur.","Frotter généreusement d’un mélange moitié sel moitié poivre.","Fumer à 120 °C au bois de chêne, côté gras vers le haut, environ 8 heures jusqu’à 74 °C à cœur.","Envelopper dans le papier boucher.","Poursuivre jusqu’à 93–95 °C à cœur et une sonde qui entre comme dans du beurre.","Laisser reposer 1 heure, trancher à contre-fil et servir sur papier avec pain, oignon et cornichons."],"photo":{"file":"File:Texas-style Brisket -smokering (15720631008).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/63/Texas-style_Brisket_-smokering_%2815720631008%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Texas-style_Brisket_-smokering_(15720631008).jpg","author":"Arnold Gatilao from Oakland, CA, USA","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"kansas-city-burnt-ends","country":"US","original":"Kansas City burnt ends","title":"Burnt ends de Kansas City (pointes de brisket caramélisées à la sauce)","en":"Kansas City burnt ends","es":"Burnt ends de Kansas City","desc":"Cubes de la pointe grasse du brisket fumé, enrobés de rub sucré et de sauce barbecue tomate-mélasse, refumés jusqu’à caramélisation, spécialité des pits de Kansas City.","cat":"Grillade","diff":"hard","prep":30,"cook":540,"serv":8,"place":{"slug":"us-kansas-city","name":"Kansas City","type":"city","lat":39.0997,"lng":-94.5786,"summary":"Capitale du barbecue sucré à la sauce tomate-mélasse et des burnt ends."},"ing":[["Pointe de brisket (point)",2.5,"kg",null],["Cassonade",4,"c. à soupe",null],["Paprika",2,"c. à soupe",null],["Sel et poivre",2,"c. à soupe",null],["Ail et oignon en poudre",2,"c. à thé",null],["Sauce barbecue Kansas City",300,"ml",null],["Miel",3,"c. à soupe",null],["Beurre",50,"g",null]],"steps":["Frotter la pointe du rub sucré.","Fumer à 120 °C environ 6 heures jusqu’à 90 °C à cœur.","Couper en cubes de 3 cm.","Les mettre dans un plat avec sauce, miel, beurre et un peu de rub.","Remettre au fumoir 2 heures à découvert en remuant jusqu’à caramélisation.","Servir chaud avec pain blanc et cornichons."],"photo":{"file":"File:Beef brisket burnt ends.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Beef_brisket_burnt_ends.jpg/1280px-Beef_brisket_burnt_ends.jpg","page":"https://commons.wikimedia.org/wiki/File:Beef_brisket_burnt_ends.jpg","author":"Gatorfan252525","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"carolina-pulled-pork","country":"US","original":"Eastern Carolina pulled pork","title":"Pulled pork de Caroline de l’Est (porc effiloché, sauce vinaigre-piment)","en":"Eastern North Carolina pulled pork","es":"Cerdo deshebrado de Carolina del Este","desc":"Épaule (ou cochon entier) fumée lentement au chêne et au hickory, effilochée et assaisonnée d’une sauce au vinaigre de cidre et au piment, servie en sandwich avec coleslaw.","cat":"Grillade","diff":"medium","prep":20,"cook":600,"serv":10,"place":{"slug":"us-north-carolina","name":"Caroline du Nord","type":"region","lat":35.5,"lng":-79,"summary":"État du barbecue au vinaigre (Est) et à la sauce tomate légère (Lexington)."},"ing":[["Épaule de porc (Boston butt)",4,"kg",null],["Sel et poivre",3,"c. à soupe",null],["Paprika",1,"c. à soupe",null],["Vinaigre de cidre",500,"ml",null],["Flocons de piment",1,"c. à soupe",null],["Sucre",2,"c. à soupe",null],["Sauce piquante",1,"c. à soupe",null],["Pains à hamburger",10,null,null],["Coleslaw",500,"g",null]],"steps":["Frotter l’épaule de sel, poivre et paprika.","Fumer à 115 °C environ 10 heures jusqu’à 93 °C à cœur.","Laisser reposer 30 minutes.","Mélanger vinaigre, piment, sucre, sauce piquante et sel.","Effilocher la viande en incorporant la peau croustillante hachée et la sauce.","Servir en sandwich avec coleslaw."],"photo":{"file":"File:Pile of Pulled Pork.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Pile_of_Pulled_Pork.jpg/1280px-Pile_of_Pulled_Pork.jpg","page":"https://commons.wikimedia.org/wiki/File:Pile_of_Pulled_Pork.jpg","author":"Michael J. Bennett","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"new-york-pizza","country":"US","original":"New York-style pizza","title":"Pizza new-yorkaise (grande part fine et souple, mozzarella sèche)","en":"New York-style pizza","es":"Pizza estilo Nueva York","desc":"Grande pizza à pâte fine et souple, cuite au four à sole, garnie de sauce tomate à l’origan et de mozzarella à faible humidité, vendue à la part pliée en deux.","cat":"Plat principal","diff":"medium","prep":30,"cook":15,"serv":8,"place":{"slug":"us-new-york-city","name":"New York","type":"city","lat":40.7128,"lng":-74.006,"summary":"Métropole des pizzas à la part, bagels au saumon, pastrami et cheesecake."},"ing":[["Farine à pain",500,"g",null],["Eau",320,"ml",null],["Levure sèche",3,"g",null],["Sel",10,"g",null],["Sucre",1,"c. à thé",null],["Huile d’olive",1,"c. à soupe",null],["Tomates broyées",400,"g",null],["Origan et ail",1,"c. à thé",null],["Mozzarella à faible humidité",350,"g","râpée"],["Parmesan",30,"g",null]],"steps":["Pétrir farine, eau, levure, sel, sucre et huile; laisser fermenter 48 heures au réfrigérateur.","Préchauffer le four à 290 °C avec une pierre pendant 1 heure.","Assaisonner les tomates crues d’origan, d’ail et de sel.","Étirer la pâte à la main en disque de 40 cm.","Étaler une fine couche de sauce puis la mozzarella.","Cuire 8 à 10 minutes; parsemer de parmesan et couper en 8 parts."],"photo":{"file":"File:NewYorkSlices.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/b/b0/NewYorkSlices.jpg","page":"https://commons.wikimedia.org/wiki/File:NewYorkSlices.jpg","author":"Lizard10979","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"bagel-lox-new-york","country":"US","original":"Bagel with lox and schmear","title":"Bagel au saumon de New York (lox, fromage à la crème, câpres)","en":"New York bagel with lox and cream cheese","es":"Bagel de Nueva York con salmón y queso crema","desc":"Bagel new-yorkais poché et cuit, tartiné de fromage à la crème, garni de saumon salé (lox), oignon rouge, câpres et tomate, institution des delis juifs de Manhattan.","cat":"Petit-déjeuner","diff":"easy","prep":10,"cook":0,"serv":4,"place":{"slug":"us-new-york-city","name":"New York","type":"city","lat":40.7128,"lng":-74.006,"summary":"Métropole des pizzas à la part, bagels au saumon, pastrami et cheesecake."},"ing":[["Bagels nature ou « everything »",4,null,null],["Fromage à la crème",200,"g",null],["Lox ou saumon fumé",250,"g",null],["Oignon rouge",0.5,null,"en fines rondelles"],["Câpres",2,"c. à soupe",null],["Tomate",1,null,"en tranches"],["Aneth",1,"poignée","facultatif"]],"steps":["Trancher les bagels en deux et les griller légèrement si désiré.","Tartiner généreusement de fromage à la crème.","Déposer les tranches de saumon.","Ajouter oignon rouge et tomate.","Parsemer de câpres et d’aneth.","Refermer ou servir ouvert."],"photo":{"file":"File:Lox-and-bagel-02.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Lox-and-bagel-02.jpg/1280px-Lox-and-bagel-02.jpg","page":"https://commons.wikimedia.org/wiki/File:Lox-and-bagel-02.jpg","author":"Kristina D.C. Hoeppner","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"cincinnati-chili","country":"US","original":"Cincinnati chili (three-way)","title":"Chili de Cincinnati « three-way » (spaghetti, chili épicé, cheddar)","en":"Cincinnati chili three-way","es":"Chili de Cincinnati three-way","desc":"Sauce à la viande fine épicée à la cannelle, au cacao et au clou de girofle, servie sur spaghetti et couverte d’une montagne de cheddar râpé, création des immigrés macédoniens de Cincinnati.","cat":"Plat principal","diff":"easy","prep":15,"cook":120,"serv":6,"place":{"slug":"us-cincinnati","name":"Cincinnati","type":"city","lat":39.1031,"lng":-84.512,"summary":"Ville de l’Ohio et de ses chili parlors (Skyline, Gold Star)."},"ing":[["Bœuf haché",1,"kg",null],["Eau",1,"l",null],["Oignon",1,null,"râpé"],["Concentré de tomate",150,"g",null],["Poudre de chili",3,"c. à soupe",null],["Cannelle",1,"c. à thé",null],["Cacao",1,"c. à soupe",null],["Clou de girofle et piment de la Jamaïque",0.5,"c. à thé",null],["Vinaigre",1,"c. à soupe",null],["Spaghetti",500,"g",null],["Cheddar fort",300,"g","râpé finement"]],"steps":["Défaire le bœuf cru dans l’eau froide (sans le dorer).","Ajouter oignon, concentré, épices, cacao et vinaigre.","Mijoter 2 heures à découvert jusqu’à sauce fluide mais nappante.","Dégraisser et saler.","Cuire les spaghetti.","Servir spaghetti, chili, puis une montagne de cheddar (three-way)."],"photo":{"file":"File:Skyline Chili three-way 2024.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Skyline_Chili_three-way_2024.jpg/1280px-Skyline_Chili_three-way_2024.jpg","page":"https://commons.wikimedia.org/wiki/File:Skyline_Chili_three-way_2024.jpg","author":"Antony-22","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chicago-italian-beef","country":"US","original":"Chicago Italian beef","title":"Italian beef de Chicago (bœuf rôti tranché trempé, giardiniera)","en":"Chicago Italian beef sandwich","es":"Italian beef de Chicago","desc":"Bœuf rôti aux herbes tranché très finement, mijoté dans son jus, servi dans un pain italien trempé (« dipped ») avec poivrons doux ou giardiniera piquante.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":180,"serv":8,"place":"us-chicago","ing":[["Haut de surlonge ou rond de bœuf",1.5,"kg",null],["Bouillon de bœuf",1,"l",null],["Ail",6,"gousses",null],["Origan, basilic, thym",1,"c. à soupe",null],["Flocons de piment et poivre",2,"c. à thé",null],["Pains italiens longs",8,null,null],["Giardiniera piquante",300,"g",null],["Poivrons verts sautés",2,null,null],["Sel",2,"c. à thé",null]],"steps":["Frotter le bœuf d’ail, herbes, sel et poivre; le rôtir à 180 °C jusqu’à 55 °C à cœur.","Laisser refroidir puis trancher le plus finement possible.","Faire mijoter le bouillon avec les jus de rôtissage, herbes et piment.","Réchauffer les tranches 1 minute dans le jus.","Garnir les pains et les tremper rapidement dans le jus.","Ajouter giardiniera ou poivrons sautés."],"photo":{"file":"File:Windy City Italian Beef.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Windy_City_Italian_Beef.jpg/1280px-Windy_City_Italian_Beef.jpg","page":"https://commons.wikimedia.org/wiki/File:Windy_City_Italian_Beef.jpg","author":"SauceSupreme","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"detroit-style-pizza","country":"US","original":"Detroit-style pizza","title":"Pizza de Détroit (rectangulaire, bords de fromage caramélisé)","en":"Detroit-style pizza","es":"Pizza estilo Detroit","desc":"Pizza épaisse cuite dans des moules rectangulaires en acier, au fromage brick qui caramélise sur les bords, avec la sauce tomate déposée en bandes sur le dessus.","cat":"Plat principal","diff":"medium","prep":30,"cook":15,"serv":4,"place":{"slug":"us-detroit","name":"Détroit","type":"city","lat":42.3314,"lng":-83.0458,"summary":"Ville de l’automobile et de la pizza carrée née chez Buddy’s en 1946."},"ing":[["Farine à pain",350,"g",null],["Eau",260,"ml",null],["Levure sèche",5,"g",null],["Sel",8,"g",null],["Huile",3,"c. à soupe","pour le moule"],["Pepperoni",80,"g",null],["Fromage brick ou mozzarella-monterey jack",350,"g","en dés"],["Sauce tomate épaisse",250,"ml",null],["Origan",1,"c. à thé",null]],"steps":["Mélanger farine, eau, levure et sel; laisser lever 2 heures.","Huiler généreusement un moule rectangulaire de 25 × 35 cm et y étirer la pâte; lever 1 heure.","Disposer le pepperoni puis le fromage jusqu’aux bords du moule.","Cuire 13 à 15 minutes à 260 °C jusqu’à ce que les bords soient noirs-caramel.","Démouler en décollant les bords croustillants.","Déposer deux bandes de sauce chaude sur le dessus et parsemer d’origan."],"photo":{"file":"File:Buddyssmallpizza.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Buddyssmallpizza.jpg/1280px-Buddyssmallpizza.jpg","page":"https://commons.wikimedia.org/wiki/File:Buddyssmallpizza.jpg","author":"Filmgod","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"hot-brown-louisville","country":"US","original":"Kentucky Hot Brown","title":"Hot Brown de Louisville (toast dinde-bacon gratiné à la Mornay)","en":"Louisville Kentucky Hot Brown","es":"Hot Brown de Louisville","desc":"Toast ouvert garni de dinde rôtie, nappé de sauce Mornay, gratiné puis couvert de bacon et de tomates, créé en 1926 à l’hôtel Brown de Louisville.","cat":"Plat principal","diff":"easy","prep":15,"cook":20,"serv":4,"place":{"slug":"us-louisville","name":"Louisville","type":"city","lat":38.2527,"lng":-85.7585,"summary":"Ville du Kentucky Derby et du Hot Brown."},"ing":[["Pain de mie épais",4,"tranches","grillées"],["Dinde rôtie",400,"g","en tranches"],["Beurre",40,"g",null],["Farine",3,"c. à soupe",null],["Crème",500,"ml",null],["Pecorino romano",60,"g","râpé"],["Bacon",8,"tranches","cuites"],["Tomates",2,null,"en tranches"],["Paprika et persil",1,"portion",null]],"steps":["Faire un roux avec beurre et farine, ajouter la crème et cuire jusqu’à épaississement.","Incorporer le fromage pour la Mornay; saler et poivrer.","Disposer les toasts dans des plats individuels et couvrir de dinde.","Napper généreusement de sauce Mornay.","Gratiner sous le gril jusqu’à ce que ce soit doré et bouillonnant.","Ajouter tomates et bacon croisé, paprika et persil."],"photo":{"file":"File:Hot Brown Kurtz.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Hot_Brown_Kurtz.jpg/1280px-Hot_Brown_Kurtz.jpg","page":"https://commons.wikimedia.org/wiki/File:Hot_Brown_Kurtz.jpg","author":"Shadle","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"spam-musubi","country":"US","original":"Spam musubi","title":"Spam musubi hawaïen (riz, Spam laqué et nori)","en":"Hawaiian Spam musubi","es":"Spam musubi hawaiano","desc":"Bloc de riz pressé surmonté d’une tranche de Spam laquée à la sauce soya sucrée, enveloppé d’une bande de nori, en-cas iconique des épiceries d’Hawaï.","cat":"Cuisine de rue","diff":"easy","prep":15,"cook":10,"serv":8,"place":"us-hawaii","ing":[["Boîte de Spam",1,null,"340 g, en 8 tranches"],["Riz japonais cuit",600,"g",null],["Sauce soya",4,"c. à soupe",null],["Sucre",3,"c. à soupe",null],["Mirin",1,"c. à soupe",null],["Feuilles de nori",4,null,"coupées en deux"],["Furikake",1,"c. à soupe","facultatif"]],"steps":["Dorer les tranches de Spam à la poêle.","Ajouter soya, sucre et mirin et laquer en retournant.","Poser une demi-feuille de nori, placer le moule à musubi (ou la boîte vide) au centre.","Tasser du riz, parsemer de furikake et poser une tranche de Spam.","Retirer le moule et enrouler le nori.","Servir tiède ou à température ambiante."],"photo":{"file":"File:Homemade Spam Musubi.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Homemade_Spam_Musubi.jpg/1280px-Homemade_Spam_Musubi.jpg","page":"https://commons.wikimedia.org/wiki/File:Homemade_Spam_Musubi.jpg","author":"Chris Hackmann","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"shrimp-and-grits","country":"US","original":"Shrimp and grits","title":"Shrimp and grits de Charleston (crevettes sur gruau de maïs crémeux)","en":"Charleston shrimp and grits","es":"Gambas con sémola de maíz de Charleston","desc":"Gruau de maïs moulu à la pierre cuit lentement au beurre et au cheddar, nappé de crevettes sautées avec bacon, oignons verts et sauce au jus, plat du Lowcountry de Caroline du Sud.","cat":"Fruits de mer","diff":"easy","prep":15,"cook":45,"serv":4,"place":{"slug":"us-charleston","name":"Charleston","type":"city","lat":32.7765,"lng":-79.9311,"summary":"Ville du Lowcountry (Caroline du Sud) : shrimp and grits, she-crab soup, Hoppin’ John."},"ing":[["Gruau de maïs moulu à la pierre (grits)",200,"g",null],["Lait et eau",1,"l",null],["Beurre",60,"g",null],["Cheddar blanc",100,"g","râpé"],["Crevettes",500,"g","décortiquées"],["Bacon",4,"tranches","en lardons"],["Ail",2,"gousses",null],["Oignons verts",4,null,null],["Jus de citron",1,"c. à soupe",null],["Sauce piquante",1,"c. à thé",null],["Sel",1,"c. à thé",null]],"steps":["Cuire les grits dans le lait et l’eau salés 40 minutes en remuant souvent.","Incorporer beurre et cheddar.","Faire dorer le bacon, retirer.","Sauter les crevettes dans le gras avec l’ail 2 minutes.","Ajouter citron, sauce piquante, oignons verts et bacon; déglacer d’un peu d’eau.","Servir les crevettes et leur jus sur les grits."],"photo":{"file":"File:Commander's Palace shrimp & grits.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/3e/Commander%27s_Palace_shrimp_%26_grits.jpg","page":"https://commons.wikimedia.org/wiki/File:Commander%27s_Palace_shrimp_%26_grits.jpg","author":"Krista","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"wisconsin-cheese-curds","country":"US","original":"Fried cheese curds","title":"Cheese curds frits du Wisconsin (caillé de cheddar pané à la bière)","en":"Wisconsin fried cheese curds","es":"Cheese curds fritos de Wisconsin","desc":"Grains de caillé de cheddar frais enrobés de pâte à la bière et frits jusqu’à être dorés, filants et « qui couinent », servis avec sauce ranch dans les foires du Wisconsin.","cat":"Entrée","diff":"easy","prep":15,"cook":10,"serv":4,"place":{"slug":"us-wisconsin","name":"Wisconsin","type":"region","lat":44.5,"lng":-89.5,"summary":"« America’s Dairyland » : cheese curds, bratwurst et supper clubs."},"ing":[["Grains de caillé de cheddar frais",450,"g",null],["Farine",150,"g",null],["Bière blonde",250,"ml","froide"],["Œuf",1,null,null],["Ail en poudre",0.5,"c. à thé",null],["Sel",1,"c. à thé",null],["Huile de friture",1,"l",null],["Sauce ranch",150,"ml",null]],"steps":["Chauffer l’huile à 190 °C.","Fouetter farine, bière, œuf, ail et sel en pâte lisse.","Tremper les grains de caillé froids dans la pâte.","Frire par petites quantités 1 minute jusqu’à ce qu’ils soient dorés.","Égoutter sur du papier.","Servir aussitôt avec sauce ranch."],"photo":{"file":"File:Crispy Cheese Curds (14492269187).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/0b/Crispy_Cheese_Curds_%2814492269187%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Crispy_Cheese_Curds_(14492269187).jpg","author":"Arnold Gatilao from Oakland, CA, USA","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"minnesota-hotdish","country":"US","original":"Tater tot hotdish","title":"Hotdish du Minnesota (gratin bœuf-haricots verts sous tater tots)","en":"Minnesota tater tot hotdish","es":"Hotdish de Minnesota","desc":"Plat unique des potlucks du Minnesota : bœuf haché, haricots verts et crème de champignons, couvert de croquettes de pommes de terre (tater tots) dorées au four.","cat":"Plat principal","diff":"easy","prep":15,"cook":50,"serv":6,"place":{"slug":"us-minnesota","name":"Minnesota","type":"region","lat":46.3,"lng":-94.3,"summary":"État des dix mille lacs, terre du hotdish et du Juicy Lucy."},"ing":[["Bœuf haché",700,"g",null],["Oignon",1,null,"haché"],["Crème de champignons en conserve",2,"boîtes",null],["Haricots verts",400,"g",null],["Maïs",200,"g","facultatif"],["Cheddar",150,"g","râpé"],["Tater tots surgelés",900,"g",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Faire dorer le bœuf avec l’oignon; égoutter.","Mélanger avec crème de champignons, haricots et maïs; assaisonner.","Étaler dans un plat de 23 × 33 cm.","Parsemer de cheddar.","Couvrir de tater tots en rangées serrées.","Cuire 45 à 50 minutes à 200 °C jusqu’à ce que les tater tots soient croustillants."],"photo":{"file":"File:Tater Tot Hot Dish 2008 Winter Carnival.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Tater_Tot_Hot_Dish_2008_Winter_Carnival.JPG/1280px-Tater_Tot_Hot_Dish_2008_Winter_Carnival.JPG","page":"https://commons.wikimedia.org/wiki/File:Tater_Tot_Hot_Dish_2008_Winter_Carnival.JPG","author":"SEWilco","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}}]$batch$::jsonb);
